// Original single-event illustration. Probabilities are assumed for one common comparison window.
export const warrantyDefinitions={
  extendedWarranty:{title:'Compare the contract price with the repair exposure it actually removes',fields:[
    ['contractPrice','All-in contract price paid at the start (CAD)',180,0,3000,10],
    ['repairCost','Repair cost if the modeled event occurs (CAD)',800,0,10000,50],
    ['deductible','Owner deductible for an eligible event (CAD)',50,0,3000,10],
    ['payoutCap','Maximum provider payment for the event (CAD)',500,0,10000,50],
    ['eventProbability','Assumed repair-event probability for the whole window (%)',40,0,100,1],
    ['eligibleShare','Assumed share of repair events eligible for payment (%)',70,0,100,1]
  ]}
};
export function warrantyComparison(input) {
  const p=input.eventProbability/100,q=input.eligibleShare/100;
  const payment=Math.min(input.payoutCap,Math.max(0,input.repairCost-input.deductible));
  const states=[
    {label:'No modeled repair',probability:1-p,without:0,with:input.contractPrice,provider:0},
    {label:'Eligible repair event',probability:p*q,without:input.repairCost,with:input.contractPrice+input.repairCost-payment,provider:payment},
    {label:'Excluded repair event',probability:p*(1-q),without:input.repairCost,with:input.contractPrice+input.repairCost,provider:0}
  ];
  const without=p*input.repairCost,expectedPayment=p*q*payment,withContract=input.contractPrice+without-expectedPayment;
  const avoidable=q*payment;
  return {p,q,payment,states,without,expectedPayment,withContract,extra:withContract-without,breakEven:avoidable>0?input.contractPrice/avoidable:null};
}
export function warrantyResult(kind,input) {
  if(kind!=='extendedWarranty')throw Error('Unknown warranty topic.');
  const p=warrantyComparison(input),grid=[0,250,500,800],shares=[25,50,75,100],range=Array.from({length:21},(_,i)=>{
    const x=i*5,v=warrantyComparison({...input,eventProbability:x});return {x,...v};
  });
  const threshold=p.breakEven==null?(input.contractPrice===0?'No modeled payment is available and the contract price is zero, so modeled costs tie at every event probability.':'No modeled provider payment is available, so no event probability can recover the positive contract price.'):(p.breakEven>1?'The cost-equality event probability exceeds 100%, so it cannot be reached in this model.':'Cost equality occurs at a whole-window event probability of '+(p.breakEven*100).toFixed(2)+'%, holding eligibility, repair size, deductible and cap fixed.');
  return {metrics:[['Expected repair cost without the extra contract',p.without,'money'],['Expected total owner cost with the extra contract',p.withContract,'money'],['Expected extra owner cost with the contract; negative means lower',p.extra,'money']],note:'Original single-event illustration, with hypothetical nominal CAD amounts and assumed probabilities for one common comparison window. There are three mutually exclusive states: no repair, one eligible repair or one excluded repair. At most one event is modeled. Eligibility is conditional on that event occurring; it is not an observed approval rate or a promise about a particular claim. For an eligible event the provider pays the smaller of the cap and the positive repair cost less the deductible; otherwise it pays zero. The contract price is paid once at the start and never refunded. The same repair price is used for eligible and excluded events. Totals ignore discounting, financing, taxes beyond entered all-in amounts, shipping, downtime, multiple failures, repair-versus-replacement choices, depreciation and claim delays. Existing manufacturer, legal and card protection are outside the numerical comparison and must be reviewed before assigning any extra benefit to the purchased contract. '+threshold,charts:[
    {id:'warranty-event-probabilities',type:'bar',title:'A failure probability is not the same as a payable-claim probability',unit:'percent',unitLabel:'Assumed probability over the whole comparison window',rows:p.states.map(s=>({label:s.label,value:s.probability})),evidence:'Hypothetical probability model',note:'Multiply the assumed repair-event probability by the eligible share to obtain the eligible-event probability. The excluded branch uses the remaining share. All three branches sum to 100% before display rounding. Eligibility is an authored scenario assumption, not measured product reliability, a denial statistic or a legal determination.'},
    {id:'warranty-state-cost',type:'groupbar',title:'Compare what the owner pays in each possible state, including the upfront price',unit:'money',seriesNames:['No extra contract','With extra contract'],rows:p.states.map(s=>({label:s.label,values:[s.without,s.with]})),evidence:'Hypothetical cash scenarios',note:'Every with-contract bar includes the contract price once, including the no-repair state. An eligible event also includes the repair cost less the provider payment. An excluded event leaves the entire repair bill with the owner. These are mutually exclusive window totals, not amounts to add together. They do not describe the timing of a reimbursement or the peak cash required before it arrives.'},
    {id:'warranty-expected-cost-bridge',type:'waterfall',title:'The contract price is certain; the provider’s modeled payment is contingent',unit:'money',rows:[{label:'Contract price',value:input.contractPrice},{label:'Expected repair cost before payment',value:p.without},{label:'Expected provider payment',value:-p.expectedPayment}],totalLabel:'Expected owner cost with contract',evidence:'Hypothetical probability model',note:'Expected provider payment equals repair probability × eligible share × payment in an eligible event. Subtract it from the contract price plus expected repair cost. This is a probability-weighted average, not a bill or a sufficient repair reserve. An actual eligible payment can differ greatly from its probability-weighted contribution.'},
    {id:'warranty-cost-probability',type:'line',title:'The crossover changes when the eligible benefit changes',unit:'money',xLabel:'Assumed whole-window repair-event probability (%)',series:[{name:'Expected owner cost: no extra contract',rows:range.map(s=>({x:s.x,value:s.without}))},{name:'Expected owner cost: with extra contract',rows:range.map(s=>({x:s.x,value:s.withContract})),dash:true}],evidence:'Hypothetical probability model',note:'Each point replaces only the repair-event probability; the contract price, eligible share, repair cost, deductible and payment cap stay fixed. The crossover is a cost-equality threshold under those assumptions, not an estimate of how likely the product is to fail. Values above 100% are infeasible. This full-range comparison curve stays unchanged when only the selected event probability changes; the headline metrics and state probabilities do update.'},
    {id:'warranty-eligibility-cap',type:'heatmap',title:'A large repair bill can still produce a small expected contract benefit',unit:'money',signed:true,compactValues:false,columns:shares.map(v=>v+'%'),rows:grid.map(payoutCap=>({label:'Cap $'+payoutCap,values:shares.map(eligibleShare=>warrantyComparison({...input,payoutCap,eligibleShare}).extra)})),evidence:'Hypothetical probability model',note:'Columns replace the eligible share conditional on a repair; rows replace the maximum provider payment. Each cell is expected owner cost with the contract minus expected repair cost without it, at the selected repair-event probability and other inputs. Positive values mean higher expected owner cost; negative values mean lower. A higher cap has no further effect once repair cost less deductible is fully covered. Read the signs and exact values rather than the colour alone.'}
  ]};
}
